from pathlib import Path
import torch,json
p=Path('/workspace/tensor_language/basis_aligned/polynomial_causal/direct_tensor_match');torch.set_num_threads(2);torch.set_grad_enabled(False);old=torch.load(p/'MIDPOINT_EXTRACTED_PROGRAM_V1.pt',weights_only=True);z=torch.load(p/'MIDPOINT_SHARED_FIT_PROGRAMS_V1.pt',weights_only=True);Sn=z['regularized_calibration_roots']['n'];Sm=z['regularized_calibration_roots']['m'];Qn,_=torch.linalg.qr(Sn@old['A'].double(),mode='reduced');Qm,_=torch.linalg.qr(Sm@old['B'].double(),mode='reduced');rows=torch.load(p/'MIDPOINT_CALIBRATION_ROWS_V1.pt',weights_only=True);n=rows['n'].flatten(0,1).double()@torch.linalg.solve(Sn,Qn);m=rows['m'].flatten(0,1).double()@torch.linalg.solve(Sm,Qm);phi=torch.einsum('bi,bj->bij',n,m).flatten(1);joint=phi.T@phi/len(n);separable=torch.kron((n.T@n/len(n)).contiguous(),(m.T@m/len(m)).contiguous());difference=float((joint-separable).norm()/joint.norm());ratios=[]
